insert into public.questions (id, topic_slug, type, text, options, multiple, invert, weight, audience) values
  ('overall.core', 'overall', 'mood5', 'Wie geht''s dir gerade mit Schule insgesamt?', null, false, false, 1, 'student'),
  ('learning.core', 'learning', 'mood5', 'Wie gut kommst du gerade mit dem Unterrichtsstoff mit?', null, false, false, 1, 'student'),
  ('stress.core', 'stress', 'mood5', 'Wie gut kommst du mit dem Druck (Tests, Noten, Hausaufgaben) klar?', null, false, false, 1, 'student'),
  ('ai.core', 'ai', 'mood5', 'Wie gut fühlst du dich beim Thema KI (ChatGPT & Co.) in der Schule begleitet?', null, false, false, 1, 'student'),
  ('wellbeing.core', 'wellbeing', 'mood5', 'Wie gut geht es dir zurzeit seelisch?', null, false, false, 1, 'student'),
  ('community.core', 'community', 'mood5', 'Wie wohl fühlst du dich in deiner Klasse / Stufe?', null, false, false, 1, 'student'),
  ('teachers.core', 'teachers', 'mood5', 'Wie fair und respektvoll fühlst du dich von deinen Lehrkräften behandelt?', null, false, false, 1, 'student'),
  ('digital.core', 'digital', 'mood5', 'Wie gut ist deine Schule digital ausgestattet (WLAN, Geräte, Tafeln)?', null, false, false, 1, 'student'),
  ('building.core', 'building', 'mood5', 'Wie wohl fühlst du dich im Schulgebäude (Räume, Toiletten, Schulhof)?', null, false, false, 1, 'student'),
  ('cancellation.core', 'cancellation', 'mood5', 'Wie zuverlässig findet dein Unterricht statt?', null, false, false, 1, 'student'),
  ('participation.core', 'participation', 'mood5', 'Wie sehr hast du das Gefühl, an deiner Schule mitreden zu können?', null, false, false, 1, 'student'),
  ('future.core', 'future', 'mood5', 'Wie gut bereitet dich die Schule auf deine Zukunft vor?', null, false, false, 1, 'student'),
  ('safety.core', 'safety', 'mood5', 'Wie sicher fühlst du dich in der Schule und auf dem Schulweg?', null, false, false, 1, 'student'),
  ('food.core', 'food', 'mood5', 'Wie zufrieden bist du mit Pausen, Essen und Trinken an der Schule?', null, false, false, 1, 'student'),
  ('phones.core', 'phones', 'mood5', 'Wie gut findest du die Handy-Regeln an deiner Schule?', null, false, false, 1, 'student'),
  ('voice.core', 'voice', 'mood5', 'Wie sehr hast du das Gefühl, dass die Politik sich für die Meinung von Schüler:innen interessiert?', null, false, false, 1, 'student'),
  ('learning.deep', 'learning', 'choice', 'Woran liegt''s?', '[{"value":"too_fast","label":"zu schnell"},{"value":"too_much","label":"zu viel"},{"value":"boring","label":"zu langweilig"},{"value":"unclear","label":"unklar erklärt"},{"value":"fits","label":"passt"}]'::jsonb, false, false, 0, 'student'),
  ('stress.deep', 'stress', 'choice', 'Was stresst am meisten?', '[{"value":"exams","label":"Klausuren-Häufung"},{"value":"homework","label":"Hausaufgaben"},{"value":"grades_future","label":"Noten/Zukunftsangst"},{"value":"parents","label":"Erwartungen Eltern"},{"value":"comparison","label":"Vergleich mit anderen"}]'::jsonb, false, false, 0, 'student'),
  ('ai.deep', 'ai', 'choice', 'Wie nutzt du KI für die Schule?', '[{"value":"none","label":"gar nicht"},{"value":"explain","label":"Erklären lassen"},{"value":"homework","label":"Hausaufgaben"},{"value":"writing","label":"Texte schreiben"},{"value":"practice","label":"Lernen/Üben"},{"value":"unsure_rules","label":"Ich weiß nicht, ob ich darf"}]'::jsonb, true, false, 0, 'student'),
  ('wellbeing.deep', 'wellbeing', 'choice', 'Hast du in der Schule jemanden, an den du dich wenden kannst?', '[{"value":"yes","label":"ja"},{"value":"unsure","label":"weiß nicht"},{"value":"no","label":"nein"}]'::jsonb, false, false, 0, 'student'),
  ('community.deep', 'community', 'choice', 'Hast du in letzter Zeit Mobbing mitbekommen (auch online)?', '[{"value":"no","label":"nein"},{"value":"others","label":"ja, bei anderen"},{"value":"me","label":"ja, bei mir"},{"value":"no_answer","label":"keine Angabe"}]'::jsonb, false, false, 0, 'student'),
  ('digital.deep', 'digital', 'choice', 'Was nervt am meisten?', '[{"value":"wifi","label":"WLAN"},{"value":"devices","label":"keine Geräte"},{"value":"broken","label":"Technik kaputt"},{"value":"teachers_dont_use","label":"Lehrkräfte nutzen es nicht"},{"value":"fits","label":"passt"}]'::jsonb, false, false, 0, 'student'),
  ('building.deep', 'building', 'choice', 'Größte Baustelle?', '[{"value":"toilets","label":"Toiletten"},{"value":"temperature","label":"Hitze/Kälte"},{"value":"broken_rooms","label":"kaputte Räume"},{"value":"space","label":"zu wenig Platz"},{"value":"cleanliness","label":"Sauberkeit"},{"value":"fits","label":"passt"}]'::jsonb, false, false, 0, 'student'),
  ('cancellation.deep', 'cancellation', 'choice', 'Wie oft fällt bei dir pro Woche etwas aus?', '[{"value":"never","label":"nie"},{"value":"1_2","label":"1–2 Std."},{"value":"3_5","label":"3–5 Std."},{"value":"more","label":"mehr"}]'::jsonb, false, false, 0, 'student'),
  ('phones.deep', 'phones', 'choice', 'Wie lautet die Regel?', '[{"value":"banned","label":"komplett verboten"},{"value":"breaks_only","label":"nur in Pausen"},{"value":"allowed_in_class","label":"im Unterricht erlaubt"},{"value":"unknown","label":"weiß nicht"}]'::jsonb, false, false, 0, 'student'),
  ('voice.deep', 'voice', 'choice', 'Wie würdest du am liebsten mitreden?', '[{"value":"online","label":"Online wie hier"},{"value":"sv","label":"über die SV"},{"value":"politicians_at_school","label":"Gespräch mit Politiker:innen an der Schule"},{"value":"youth_parliament","label":"Jugendparlament/Schülervertretung auf Landesebene"},{"value":"none","label":"gar nicht"}]'::jsonb, true, false, 0, 'student'),
  ('ai.swipe.explain', 'ai', 'swipe', 'Meine Lehrkräfte erklären, wie man KI sinnvoll nutzt.', null, false, false, 0.5, 'student'),
  ('ai.swipe.rules', 'ai', 'swipe', 'Es ist klar geregelt, wann ich KI benutzen darf.', null, false, false, 0.5, 'student'),
  ('stress.swipe.freetime', 'stress', 'swipe', 'Ich habe genug Freizeit neben der Schule.', null, false, false, 0.5, 'student'),
  ('learning.swipe.why', 'learning', 'swipe', 'Ich weiß, wofür ich das lerne, was wir gerade machen.', null, false, false, 0.5, 'student'),
  ('wellbeing.swipe.sleep', 'wellbeing', 'swipe', 'Ich schlafe unter der Woche genug.', null, false, false, 0.5, 'student'),
  ('digital.swipe.wifi', 'digital', 'swipe', 'Das WLAN funktioniert, wenn wir es brauchen.', null, false, false, 0.5, 'student'),
  ('participation.swipe.sv', 'participation', 'swipe', 'Unsere SV kann wirklich etwas verändern.', null, false, false, 0.5, 'student'),
  ('building.swipe.toilet', 'building', 'swipe', 'Ich gehe in der Schule ohne Bedenken auf die Toilette.', null, false, false, 0.5, 'student'),
  ('voice.swipe.change', 'voice', 'swipe', 'Wenn wir Schüler:innen Probleme ansprechen, ändert sich auch etwas.', null, false, false, 0.5, 'student'),
  ('voice.swipe.talk', 'voice', 'swipe', 'Ich würde gern direkt mit Politiker:innen über Schule sprechen.', null, false, false, 0, 'student'),
  ('safety.swipe.conflict', 'safety', 'swipe', 'Wenn es an meiner Schule Streit gibt, wird er gut gelöst.', null, false, false, 0.5, 'student')
